"""Diagnostic (read-only) and repair (typed, validated) PowerShell templates used by the AI agent.

Every template is a fixed script with validated parameters. Nothing here is generated by a model. They use CIM classes (not localized
performance-counter paths) so they behave the same on English and Arabic Windows. Read templates never change the machine.
"""
from __future__ import annotations

from .service import CoreError

NAME_RX = r"^[A-Za-z0-9_.-]{1,64}$"
# Never stop these through the agent: Windows itself, the security stack, and the CIT controller/Worker/model runtime.
PROTECTED_PROCESSES = {"system", "idle", "registry", "smss", "csrss", "wininit", "winlogon", "services", "lsass", "svchost", "fontdrvhost", "dwm", "explorer", "msmpeng", "securityhealthservice",
                       "python", "pythonw", "uvicorn", "ollama", "ollama app", "cit-worker", "rustdesk", "claude", "node", "adb", "tailscale", "tailscaled", "docker", "dockerd", "powershell", "pwsh", "cmd", "conhost", "sihost", "taskhostw", "runtimebroker", "spoolsv"}


def ps(script: str) -> dict:
    return {"shell": "powershell", "body": script}


def _json(script: str) -> dict:
    return ps(script + " | ConvertTo-Json -Compress -Depth 5")


PERF = (
    "$ErrorActionPreference='SilentlyContinue'; $os=Get-CimInstance Win32_OperatingSystem; "
    "$cores=[int](Get-CimInstance Win32_Processor | Measure-Object NumberOfLogicalProcessors -Sum).Sum; if(-not $cores){$cores=1}; "
    "$l=@(); 1..3 | ForEach-Object { $l += [int](Get-CimInstance Win32_Processor | Measure-Object LoadPercentage -Average).Average; Start-Sleep -Milliseconds 400 }; "
    "$a=@{}; Get-Process | ForEach-Object { $a[$_.Id]=$_.CPU }; Start-Sleep -Seconds 1; "
    "$p=@(Get-Process | ForEach-Object { $d=0; if($a.ContainsKey($_.Id) -and $_.CPU -ne $null -and $a[$_.Id] -ne $null){ $d=$_.CPU-$a[$_.Id] }; "
    "[pscustomobject]@{Id=$_.Id;ProcessName=$_.ProcessName;cpu_pct=[math]::Round($d/$cores*100,1);mem_mb=[math]::Round($_.WorkingSet64/1MB,1)} }); "
    "$disk=Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter \"Name='_Total'\"; "
    "$boot=$os.LastBootUpTime; $cs=Get-CimInstance Win32_ComputerSystem; "
    "[pscustomobject]@{host=$env:COMPUTERNAME; cores=$cores; cpu_pct=[int](($l | Measure-Object -Average).Average); "
    "mem_total_mb=[math]::Round($os.TotalVisibleMemorySize/1KB); mem_free_mb=[math]::Round($os.FreePhysicalMemory/1KB); "
    "commit_total_mb=[math]::Round($os.TotalVirtualMemorySize/1KB); commit_free_mb=[math]::Round($os.FreeVirtualMemory/1KB); "
    "disk_busy_pct=[int]$disk.PercentDiskTime; disk_queue=[double]$disk.CurrentDiskQueueLength; disk_ms=[math]::Round([double]$disk.AvgDisksecPerTransfer*1000,1); "
    "uptime_hours=[math]::Round(((Get-Date)-$boot).TotalHours,1); proc_count=$p.Count; "
    "top_cpu=@($p | Sort-Object cpu_pct -Descending | Select-Object -First 6); top_mem=@($p | Sort-Object mem_mb -Descending | Select-Object -First 6)}"
)
STARTUP = ("$ErrorActionPreference='SilentlyContinue'; $i=@(Get-CimInstance Win32_StartupCommand | Select-Object Name,Command,Location,User); "
           "[pscustomobject]@{count=$i.Count; items=@($i | Select-Object -First 40)}")
HEALTH = (
    "$ErrorActionPreference='SilentlyContinue'; $mp=Get-MpComputerStatus; "
    "$rb=[bool]((Test-Path 'HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\WindowsUpdate\\Auto Update\\RebootRequired') -or (Test-Path 'HKLM:\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Component Based Servicing\\RebootPending') -or (Test-Path 'HKLM:\\SYSTEM\\CurrentControlSet\\Control\\Session Manager\\PendingFileRenameOperations')); "
    "$cr=@(Get-WinEvent -FilterHashtable @{LogName='Application';ProviderName='Application Error','Application Hang';StartTime=(Get-Date).AddHours(-72)} -MaxEvents 30 | ForEach-Object { [pscustomobject]@{time=$_.TimeCreated.ToString('s');id=$_.Id;app=[string]$_.Properties[0].Value} }); "
    "$wu=@(Get-WinEvent -FilterHashtable @{LogName='System';ProviderName='Microsoft-Windows-WindowsUpdateClient';Level=2,3;StartTime=(Get-Date).AddDays(-7)} -MaxEvents 20 | ForEach-Object { [pscustomobject]@{time=$_.TimeCreated.ToString('s');id=$_.Id;msg=(($_.Message -split \"`n\")[0])} }); "
    "[pscustomobject]@{reboot_pending=$rb; defender=@{present=[bool]$mp; service=$mp.AMServiceEnabled; realtime=$mp.RealTimeProtectionEnabled; signature_age_days=$mp.AntivirusSignatureAge}; "
    "bad_devices=@(Get-CimInstance Win32_PnPEntity -Filter 'ConfigManagerErrorCode<>0 AND ConfigManagerErrorCode<>22 AND ConfigManagerErrorCode<>24 AND ConfigManagerErrorCode<>45 AND ConfigManagerErrorCode<>21' | Select-Object -First 10 Name,Description,PNPClass,ConfigManagerErrorCode); "
    "disks=@(Get-PhysicalDisk | Select-Object FriendlyName,HealthStatus,OperationalStatus); firewall=@(Get-NetFirewallProfile | Select-Object Name,Enabled); "
    "crashes=$cr; update_errors=$wu}"
)
NETDEEP = (
    "$ErrorActionPreference='SilentlyContinue'; $gw=(Get-NetRoute -DestinationPrefix '0.0.0.0/0' | Sort-Object RouteMetric | Select-Object -First 1).NextHop; "
    "$g=@(); if($gw){ $g=@(Test-Connection -ComputerName $gw -Count 4) }; $n=@(Test-Connection -ComputerName 1.1.1.1 -Count 4); "
    "$dns=[math]::Round((Measure-Command { Resolve-DnsName example.com -DnsOnly }).TotalMilliseconds); $res=[bool](Resolve-DnsName example.com -DnsOnly); "
    "$sig=(netsh wlan show interfaces | Select-String '^\\s*Signal' | Select-Object -First 1); "
    "$px=(Get-ItemProperty 'HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings'); "
    "[pscustomobject]@{gateway=$gw; gw_sent=4; gw_recv=$g.Count; gw_ms=if($g.Count){[math]::Round(($g | Measure-Object ResponseTime -Average).Average,1)}else{$null}; "
    "net_recv=$n.Count; net_ms=if($n.Count){[math]::Round(($n | Measure-Object ResponseTime -Average).Average,1)}else{$null}; dns_ms=$dns; dns_resolves=$res; "
    "wifi_signal=if($sig){[int](($sig.ToString() -split ':')[1].Trim().TrimEnd('%'))}else{$null}; proxy_enabled=[bool]$px.ProxyEnable; proxy=$px.ProxyServer; "
    "adapters=@(Get-NetAdapter | Where-Object Status -eq 'Up' | Select-Object Name,LinkSpeed); firewall=@(Get-NetFirewallProfile | Select-Object Name,Enabled); "
    "events=@(Get-WinEvent -FilterHashtable @{LogName='System';ProviderName='Tcpip','Microsoft-Windows-DNS-Client','Microsoft-Windows-WLAN-AutoConfig','Netwtw06','Netwtw08','e1dexpress';Level=2,3;StartTime=(Get-Date).AddHours(-24)} -MaxEvents 15 | ForEach-Object { [pscustomobject]@{time=$_.TimeCreated.ToString('s');provider=$_.ProviderName;id=$_.Id} })}"
)


def _stop_process(p: dict) -> dict:
    n = p["name"]
    if n.lower() in PROTECTED_PROCESSES or n.lower().startswith(("cit", "ollama", "claude", "python")):
        raise CoreError("that process is protected and cannot be stopped by CIT", 422)
    return ps(f"$p=@(Get-Process -Name '{n}' -ErrorAction Stop); $p | ForEach-Object {{ [void]$_.CloseMainWindow() }}; Start-Sleep -Seconds 5; "
              f"$left=@(Get-Process -Name '{n}' -ErrorAction SilentlyContinue); $left | Stop-Process -Force -ErrorAction SilentlyContinue; "
              f"@{{stopped=$p.Count; forced=$left.Count}} | ConvertTo-Json -Compress")


EXTRA: dict[str, dict] = {
    "perf.snapshot": {"title": "Performance snapshot (CPU, memory, disk response, top processes)", "risk": "read", "params": {}, "build": lambda p: _json(PERF)},
    "startup.apps": {"title": "Startup applications", "risk": "read", "params": {}, "build": lambda p: _json(STARTUP)},
    "health.windows": {"title": "Windows health (reboot, Defender, drivers, disks, crashes, update errors)", "risk": "read", "params": {}, "build": lambda p: _json(HEALTH)},
    "net.deep": {"title": "Deep network check (gateway/internet latency and loss, DNS time, Wi-Fi, proxy, firewall, events)", "risk": "read", "params": {}, "build": lambda p: _json(NETDEEP)},
    "cleanup.temp": {"title": "Remove temporary files older than 3 days (files only)", "risk": "modify", "params": {}, "build": lambda p: ps(
        "$ErrorActionPreference='SilentlyContinue'; $cut=(Get-Date).AddDays(-3); $f=@(Get-ChildItem $env:TEMP -Recurse -Force -File | Where-Object { $_.LastWriteTime -lt $cut }); "
        "$mb=[math]::Round((($f | Measure-Object Length -Sum).Sum)/1MB,1); $f | Remove-Item -Force; [pscustomobject]@{candidates=$f.Count; freed_mb=$mb} | ConvertTo-Json -Compress")},
    "dns.flush": {"title": "Flush the DNS resolver cache", "risk": "modify", "params": {}, "build": lambda p: ps("Clear-DnsClientCache -ErrorAction Stop; 'dns cache cleared'")},
    "service.start": {"title": "Start a stopped Windows service", "risk": "modify", "params": {"name": NAME_RX}, "build": lambda p: ps(
        f"$s=Get-Service -Name '{p['name']}' -ErrorAction Stop; if($s.Status -ne 'Running'){{ Start-Service -Name '{p['name']}' -ErrorAction Stop }}; (Get-Service '{p['name']}').Status.ToString()")},
    "process.stop": {"title": "Close an application (asks it to close, then ends it)", "risk": "modify", "params": {"name": NAME_RX}, "build": _stop_process},
}
EXTRA_INVENTORY = ("perf.snapshot", "startup.apps", "health.windows", "net.deep")
